using System;

public class TreeNode {
    public int val; public TreeNode left, right;
    public TreeNode(int val=0, TreeNode left=null, TreeNode right=null){this.val=val;this.left=left;this.right=right;}
}

public class Solution {
    public bool IsSameTree(TreeNode p, TreeNode q) {

        // both empty — same
        if (p == null && q == null) return true;

        // one empty, one not — different
        if (p == null || q == null) return false;

        return (p.val == q.val) && IsSameTree(p.left, q.left) && IsSameTree(p.right, q.right);
    }
}

class Program {
    static void Main() {
        var sol = new Solution();
        var p1 = new TreeNode(1, new TreeNode(2), new TreeNode(3));
        var q1 = new TreeNode(1, new TreeNode(2), new TreeNode(3));
        Console.WriteLine(sol.IsSameTree(p1, q1)); // true

        var p2 = new TreeNode(1, new TreeNode(2), null);
        var q2 = new TreeNode(1, null, new TreeNode(2));
        Console.WriteLine(sol.IsSameTree(p2, q2)); // false
    }
}

