public class ListNode {
    public int val;
    public ListNode next;
    public ListNode(int val=0, ListNode next=null) { this.val=val; this.next=next; }
}

public class Solution {
    public ListNode MergeTwoLists(ListNode list1, ListNode list2) {

        ListNode currFirstList = list1;
        ListNode currSecondList = list2;
        ListNode dummyNode = new ListNode(0);
        ListNode curr = dummyNode;

        while(currFirstList!=null && currSecondList!=null){

            if(currFirstList.val < currSecondList.val){
                curr.next = currFirstList;
                currFirstList = currFirstList.next;
                curr = curr.next;
            }
            else{
                curr.next = currSecondList;
                currSecondList = currSecondList.next;
                curr = curr.next;
            }            
        }

         curr.next = currFirstList ?? currSecondList;
         return dummyNode.next;

    }
}

class Program {
    static ListNode Make(int[] arr) {
        if (arr.Length == 0) return null;
        var head = new ListNode(arr[0]);
        var cur = head;
        for (int i = 1; i < arr.Length; i++) { cur.next = new ListNode(arr[i]); cur = cur.next; }
        return head;
    }
    static string Print(ListNode head) {
        var parts = new System.Collections.Generic.List<string>();
        while (head != null) { parts.Add(head.val.ToString()); head = head.next; }
        return "[" + string.Join(",", parts) + "]";
    }
    static void Main() {
        var sol = new Solution();
        Console.WriteLine(Print(sol.MergeTwoLists(Make(new int[]{1,2,4}), Make(new int[]{1,3,4})))); // [1,1,2,3,4,4]
    }
}

