public class Solution {
    public IList<string> GenerateParenthesis(int n) {
        // Your solution here
        var result = new List<string>();
        Build(result, "", 0, 0, n);
        return result;

    }

    public void Build(List<string> result, string current, int leftUsed, int rightUsed, int n){

        if(current.Length==2*n){
            result.Add(current);
            return;
        }

        if(leftUsed<n){
            Build(result, current+"(",leftUsed+1,rightUsed,n);
        }

        if(rightUsed < leftUsed){
            Build(result, current+")",leftUsed,rightUsed+1,n);
        }

    }
}

