// Approach: backward scan from every element — O(n^2)

public class Solution {
    public int LongestConsecutive(int[] nums) {
        // Your solution here
        HashSet<int> hashSet = GetUniquNumsInArr(nums);
        int maxSeqLen = 1;

        for (int i = 0; i < nums.Length; i++) {

            int seqLen = 1;
            int placeToCheck = 1;

            while(hashSet.Contains(nums[i]-placeToCheck)){
                placeToCheck++;
                seqLen++;
            }

            maxSeqLen = Math.Max(maxSeqLen, seqLen);
            continue;
        }

        return maxSeqLen;
    }

    public static HashSet<int> GetUniquNumsInArr(int[] nums){

        HashSet<int> hashSet = new HashSet<int>();

        foreach (var num in nums)
        {
            hashSet.Add(num);
        }

        return hashSet;
    }
}

