public class Solution {
    public int Search(int[] nums, int target) {

        int indMin=FindIndOfMin(nums);

        if(target==nums[indMin]){
            return indMin;
        }


        bool leftSearch = target>nums[nums.Length-1];

        int l =-1;
        int r=-1;

        if(leftSearch){
            l=0;
            r=indMin-1;
        }else{
            l = indMin + 1;
            if (l >= nums.Length) return -1;  
            r = nums.Length - 1;
        }

        while(l<r){
            int mid=(l+r)/2;
            if(target==nums[mid]){
                return mid;
            }
            else if(target>nums[mid]){
                l=mid+1;
            }
            else{
                r=mid-1;
            }
        }

        if(target==nums[l]){
            return l;
        }

        return -1;

    }

    public int FindIndOfMin(int[] nums) {

        // Your solution here
        int l=0;
        int r=nums.Length-1;

        while(l<r){
            int mid=(l+r)/2;
            if(nums[mid]>nums[r]){
                l=mid+1;
            }
            else{
                r=mid;
            }
        }

        return l;
    }
}

class Program {
    static void Main() {
        var sol = new Solution();
         Console.WriteLine(sol.Search(new int[]{4,5,6,7,0,1,2}, 0)); // 4  — target in right half
        Console.WriteLine(sol.Search(new int[]{4,5,6,7,0,1,2}, 6)); // 2  — target in left half
        Console.WriteLine(sol.Search(new int[]{4,5,6,7,0,1,2}, 3)); // -1 — not found
        Console.WriteLine(sol.Search(new int[]{1}, 1));              // 0  — single element found
        Console.WriteLine(sol.Search(new int[]{1}, 0));              // -1 — single element not found
        Console.WriteLine(sol.Search(new int[]{1,2,3,4,5}, 3));     // 2  — no rotation
        Console.WriteLine(sol.Search(new int[]{3,1}, 1));            // 1  — two elements, target at end
        Console.WriteLine(sol.Search(new int[]{5,1,3}, 3));          // 2  — target at last position
