using System;
using System.Collections.Generic;

public class Solution {
    public int[][] KClosest(int[][] points, int k) {
        // Your solution here
        PriorityQueue<int[], int> queue = new PriorityQueue<int[], int>();

        foreach (int[] point in points)
        {
            int sqr = point[0]*point[0]+point[1]*point[1];

            if(queue.Count<k){
                queue.Enqueue(point,-sqr);
            }
            else {
                queue.TryPeek(out _, out int topPriority);
                if (sqr < -topPriority) {
                    queue.DequeueEnqueue(point, -sqr);
                }
            }
        }

        int[][] result = new int[k][];

        for (int i = 0; i < k; i++) {
            result[i] = queue.Dequeue();
        }

        return result;
    }
}

class Program {
    static void Main() {
        var sol = new Solution();
        var r1 = sol.KClosest(new int[][]{ new int[]{1,3}, new int[]{-2,2} }, 1);
        foreach(var p in r1) Console.WriteLine($"[{p[0]},{p[1]}]"); // [-2,2]

        var r2 = sol.KClosest(new int[][]{ new int[]{3,3}, new int[]{5,-1}, new int[]{-2,4} }, 2);
        foreach(var p in r2) Console.WriteLine($"[{p[0]},{p[1]}]"); // [3,3] [-2,4]
    }
}

