using System;

public class Solution {
    public int LongestCommonSubsequence(string text1, string text2) {

        // length of LCS of first i chars of text1 and first j chars of text2.
         int[,] dp = new int[text1.Length + 1, text2.Length + 1];

         for(int i = 1; i<=text1.Length; i++){
             for(int j = 1; j<=text2.Length; j++){
                if(text1[i-1]==text2[j-1]){
                    dp[i,j] = dp[i-1,j-1] + 1;
                }
                else{
                    dp[i,j] = Math.Max(dp[i-1,j], dp[i,j-1]);
                }
             }
         }

        return dp[text1.Length, text2.Length];

    }
}

class Program {
    static void Main() {
        var sol = new Solution();
        Console.WriteLine(sol.LongestCommonSubsequence("abcde", "ace")); // 3
        Console.WriteLine(sol.LongestCommonSubsequence("abc", "abc"));   // 3
        Console.WriteLine(sol.LongestCommonSubsequence("abc", "def"));   // 0
    }
}

