using System;
using System.Collections.Generic;

public class Solution {
    public int OrangesRotting(int[][] grid) {
        // Your solution here
        Queue<(int, int)> queue = new Queue<(int, int)>();

        int fresh = 0;

        for(int i = 0; i<grid.Length; i++){
            for(int j = 0; j<grid[0].Length; j++){
                if(grid[i][j]==2){
                    queue.Enqueue((i, j));
                }
                else if(grid[i][j]==1){
                    fresh++;
                }
            }
        }

         if(fresh == 0) return 0;

        int[][] dirs = new int[][]{ new int[]{1,0}, new int[]{-1,0}, new int[]{0,1}, new int[]{0,-1} };
        int minutes = 0;
        while(queue.Count>0){

            int count = queue.Count;

            for(int k = 0; k < count; k++){
                // dequeue and process one orange
                (int rottenI, int rottenJ)  = queue.Dequeue();
                foreach(var dir in dirs){
                    int ni = rottenI + dir[0];
                    int nj = rottenJ + dir[1];

                    if(ni<0 || nj<0 || ni>=grid.Length || nj>=grid[0].Length){
                        continue;
                    }

                    if(grid[ni][nj]==1){
                        grid[ni][nj] = 2;
                        queue.Enqueue((ni,nj));
                        fresh--;
                    }
                }
            }

            minutes++;
        }

        return fresh == 0 ? minutes - 1 : -1;
    }
}

class Program {
    static void Main() {
        var sol = new Solution();
        Console.WriteLine(sol.OrangesRotting(new int[][]{ new int[]{2,1,1}, new int[]{1,1,0}, new int[]{0,1,1} })); // 4
        Console.WriteLine(sol.OrangesRotting(new int[][]{ new int[]{2,1,1}, new int[]{0,1,1}, new int[]{1,0,1} })); // -1
        Console.WriteLine(sol.OrangesRotting(new int[][]{ new int[]{0,2} })); // 0
    }
}

