using System;

public class Solution {
    public void Solve(char[][] board) {
        int r = board.Length;
        int c = board[0].Length;

        // Top and bottom rows
        for (int j = 0; j < c; j++) {
            if (board[0][j] == 'O') DFS(board, 0, j);
            if (board[r-1][j] == 'O') DFS(board, r-1, j);
        }

        // Left and right columns
        for (int i = 0; i < r; i++) {
            if (board[i][0] == 'O') DFS(board, i, 0);
            if (board[i][c-1] == 'O') DFS(board, i, c-1);
        }

        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (board[i][j] == 'O') board[i][j] = 'X';
                else if (board[i][j] == 'S') board[i][j] = 'O';
            }
        }

    }

    public void DFS(char[][] board, int i , int j){

        if(i<0 || i>=board.Length || j<0 || j>= board[0].Length){
            return;
        }

        if(board[i][j]!='O'){
            return;
        }

        board[i][j]='S';

        DFS(board, i+1, j);
        DFS(board, i-1, j);
        DFS(board, i, j+1);
        DFS(board, i, j-1);

    }
}

class Program {
    static void Main() {
        var sol = new Solution();
        var b = new char[][]{
            new char[]{'X','X','X','X'},
            new char[]{'X','O','O','X'},
            new char[]{'X','X','O','X'},
            new char[]{'X','O','X','X'}
        };
        sol.Solve(b);
        foreach(var row in b) Console.WriteLine(string.Join("",row));
        // XXXX / XXXX / XXXX / XOXX
    }
}

