public class TreeNode {
    public int val; public TreeNode left, right;
    public TreeNode(int val=0, TreeNode left=null, TreeNode right=null){this.val=val;this.left=left;this.right=right;}
}

public class Solution {
    public TreeNode LowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        // Your solution here
        if(root ==  null || root == p || root ==q){
            return root;
        }

        bool isPInLeftSubtree = IsNodeInTree(root.left, p);

        bool isQInLeftSubtree = IsNodeInTree(root.left, q);

        if(isPInLeftSubtree != isQInLeftSubtree){
            return root;
        }

        if(isPInLeftSubtree){
            return LowestCommonAncestor(root.left, p,q);
        }
        else{
            return LowestCommonAncestor(root.right,p,q);
        }

    }

    public bool IsNodeInTree(TreeNode root, TreeNode node)
    {
        if(root == null)
        {
            return false;
        }

        if(root == node)
        {
            return true;
        }

        return IsNodeInTree(root.left, node) || IsNodeInTree(root.right, node);
    }
}

class Program {
    static void Main() {
        var sol = new Solution();
        var root = new TreeNode(3,
        new TreeNode(5, new TreeNode(6), new TreeNode(2, new TreeNode(7), new TreeNode(4))),
        new TreeNode(1, new TreeNode(0), new TreeNode(8)));
