    private ListNode GetMid(ListNode head){
        ListNode slow = head;
        ListNode fast = head.Next;

        while (fast != null && fast.Next != null) {
            slow = slow.Next;
            fast = fast.Next.Next;
        }

        return slow;
    }

    private ListNode Reverse(ListNode head){

        ListNode prev = null;
        ListNode curr = head;

        while(curr!=null){
            ListNode temp = curr.Next;
            curr.Next = prev;
            prev=curr;
            curr = temp;
        }

        return prev;
    }

    private Merge(ListNode first, ListNode second){

        ListNode firstCurr = first;
        ListNode secondCurr = second;

        while (secondCurr != null) {
            ListNode fNext = firstCurr.next;   // save both nexts
            ListNode sNext = secondCurr.next;

            firstCurr.next = secondCurr;       // 1 → 5
            secondCurr.next = fNext;           // 5 → 2

            firstCurr = fNext;                 // move to 2
            secondCurr = sNext;               // move to 4
        }

    }

}

