public class Solution {
    public int NumIslands(char[][] grid) {
        int result = 0;
        for(int r=0;r<grid.Length; r++){
            for(int c = 0; c<grid[r].Length; c++){
                if(grid[r][c]=='1'){
                    result++;
                    DFS(grid,r,c);
                }
            }
        }   

        return result;     

    }

    private void DFS(char[][] grid, int r, int c){
        if(r>=grid.Length || r<0){
            return;
        }

        if(c>=grid[0].Length || c<0){
            return;
        }

        if(grid[r][c] != '1'){
            return;
        }

        grid[r][c] = '0';

        DFS(grid, r + 1, c);
        DFS(grid, r - 1, c);
        DFS(grid, r, c+1);
        DFS(grid, r, c-1);
    }
}

