    public LRUCache(int capacity) {
        this.capacity = capacity;
        dict = new Dictionary<int, Node>();

        head = new Node();
        tail = new Node();
        head.next = tail;
        tail.prev = head;
    }

    public int Get(int key) {
        // get from dict
        if (dict.TryGetValue(key, out Node node)) {
            //  move this to near tail
            Node previousToFoundNode = node.prev;
            Node nextToFoundNode = node.next;

            previousToFoundNode.next = nextToFoundNode;
            nextToFoundNode.prev = previousToFoundNode;

            // now node is hanging
            Node beforeTail = tail.prev;
            tail.prev= node;
            beforeTail.next = node;
            node.prev  = beforeTail;
            node.next =  tail;

            // return Node val
            return node.val;
        } else {
            // not found
            return -1;
        }
    }

    public void Put(int key, int value) {

        // check if key xists
        if (dict.TryGetValue(key, out Node node)) {
            // update value
            node.val = value;
            // move to latest
            //  move this to near tail
            Node previousToFoundNode = node.prev;
            Node nextToFoundNode = node.next;

            previousToFoundNode.next = nextToFoundNode;
            nextToFoundNode.prev = previousToFoundNode;

            // now node is hanging
            Node beforeTail = tail.prev;
            tail.prev= node;
            beforeTail.next = node;
            node.prev  = beforeTail;
            node.next =  tail;

            // update dict
            dict[key]=node;
        }
        else{
            // create new node
            Node newNode = new Node();
            newNode.key = key;
            newNode.val = value;

            // insert before tail
            Node beforeTail = tail.prev;
            tail.prev= newNode;
            beforeTail.next = newNode;
            newNode.prev  = beforeTail;
            newNode.next =  tail;

            // update dict
            dict[key]=newNode;

            if (dict.Count > capacity) {
                // evict nxt to had
                Node nodeToBeEvicted = head.next;
                head.next = nodeToBeEvicted.next;
                nodeToBeEvicted.next.prev = head;

                int keyToEmpty = nodeToBeEvicted.key;
                dict.Remove(keyToEmpty);
            }

        }
    }
}

class Program {
    static void Main() {
        var cache = new LRUCache(2);
        cache.Put(1,1);
        cache.Put(2,2);
        Console.WriteLine(cache.Get(1));   // 1
        cache.Put(3,3);                    // evicts key 2
        Console.WriteLine(cache.Get(2));   // -1
        cache.Put(4,4);                    // evicts key 1
        Console.WriteLine(cache.Get(1));   // -1
        Console.WriteLine(cache.Get(3));   // 3
        Console.WriteLine(cache.Get(4));   // 4
    }
}

