public IList<string> Decode(string s) {
    IList<string> strs = new List<string>();

    for (int i = 0; i < s.Length; ) {
        int j = s.IndexOf('#', i);   // find # starting from i
        int len = int.Parse(s.Substring(i, j - i));  // number before #
        string str = s.Substring(j + 1, len);        // grab exactly len chars after #
        strs.Add(str);
        i = j + 1 + len;             // jump i forward
    }

     return strs;
}
}

