public class Solution {
    public int LeastInterval(char[] tasks, int n) {
        // Your solution here
        Dictionary<char, int> freqMap = BuildFreqMap(tasks);
        int maxFreq = GetMaxFreq(freqMap);
        int countMaxFreq = CountMaxFreq(freqMap,maxFreq);
        int result = (maxFreq - 1) * (n + 1) + countMaxFreq;
        return Math.Max(result, tasks.Length);

    }

    public Dictionary<char, int> BuildFreqMap(char[] tasks){

        Dictionary<char, int> result = new Dictionary<char, int>();

        foreach (char task in tasks)
        {
            if(result.ContainsKey(task)){
                result[task]++;
            }
            else{
                result[task] = 1;
            }
        }

        return result;
    }

    public int GetMaxFreq(Dictionary<char, int> freqMap){
        int max= int.MinValue;

        foreach (int freq in freqMap.Values)
        {
            max = Math.Max(freq, max);
        }

        return max;
    }

    public int CountMaxFreq(Dictionary<char, int> freqMap, int max){
        int count= 0;

        foreach (int freq in freqMap.Values)
        {
            if(freq==max){
                count++;
            }
        }

        return count;
    }
}

