public class Solution {
    public IList<int> RightSideView(TreeNode root) {
        // Your solution here
        IList<List<int>> bfs = BFS(root);
        IList<int> result = [];

        foreach (var item in bfs)
        {
            result.Add(item[item.Count-1]);
        }

        return result;
    }

    public IList<List<int>> BFS(TreeNode root)
    {
        IList<List<int>> result = new List<List<int>>();

        if(root == null)
        return result;

        Queue<TreeNode> queue = new Queue<TreeNode>();

        queue.Enqueue(root);

        int currLevel = 0;

        while(queue.Count > 0)
        {
            int len = queue.Count;

            result.Add(new List<int>());

            for(int i = 0; i < len; i++)
            {
                TreeNode node = queue.Dequeue();

                result[currLevel].Add(node.val);

                if(node.left != null)
                queue.Enqueue(node.left);

                if(node.right != null)
                queue.Enqueue(node.right);
            }

            currLevel++;
        }

        return result;
    }
}

