public class Solution {

    public bool CheckInclusion(string s1, string s2) {

        if (s1.Length > s2.Length)
        {
            return false;
        }

        // Your solution here
        int[] s1Count = GetFreqArray(s1);

        int windowLen = s1.Length;
        int windowStart = 0;
        int windowEnd = windowLen + windowStart -1;
        int[] windowCount = new int[26];

        for (int i = windowStart; i <= windowEnd; i++)
        {
            int idx = s2[i] - 'a';
            windowCount[idx]++;
        }

        while(windowEnd < s2.Length){

            if (AreEqual(s1Count, windowCount))
            {
                return true;
            }

            int leftIndex = s2[windowStart] - 'a';
            windowCount[leftIndex]--;

             windowStart++;
             windowEnd++;

            if (windowEnd < s2.Length)
            {
                int rightIndex = s2[windowEnd] - 'a';
                windowCount[rightIndex]++;
            }
        }

        return false;
    }

    public int[] GetFreqArray(string s)
    {
        int[] charCount = new int[26];

        foreach (char c in s)
        {
            int idx = c - 'a';
            charCount[idx]++;
        }

        return charCount;
    }

    public bool AreEqual(int[] first, int[] second)
    {
        for (int i = 0; i < 26; i++)
        {
            if (first[i] != second[i])
            {
                return false;
            }
        }

        return true;
    }
}

