public class Solution {
    public IList<IList<int>> Subsets(int[] nums) {
        List<IList<int>> result = new List<IList<int>>();
        List<int> current = [];
        dsa(nums,0,current,result);
        return result;
    }

    public void dsa(int[] nums, int i, List<int> current,  List<IList<int>> result){
        if(i>=nums.Length){
            result.Add(new List<int>(current));
            return;
        }

        // skip
        dsa(nums,i+1,current,result);

        // include 
        current.Add(nums[i]);
        dsa(nums,i+1,current,result);
        // remove previos for backtrack
        current.RemoveAt(current.Count-1);
    }
}

