using System;

public class ListNode {
    public int val; public ListNode next;
    public ListNode(int val=0, ListNode next=null){this.val=val;this.next=next;}
}

public class Solution {
    public ListNode AddTwoNumbers(ListNode l1, ListNode l2) {
        ListNode dummyNode = new ListNode(0);
        ListNode resultCurr = dummyNode;
        ListNode firstCurr = l1;
        ListNode secondCurr = l2;
        int carry = 0;

        while(firstCurr!=null || secondCurr!=null){
            int a = firstCurr != null ? firstCurr.val : 0;
            int b = secondCurr != null ? secondCurr.val : 0;
            int sum = a + b + carry;
            (int digit, carry) = Decompose(sum);

            resultCurr.next = new ListNode(digit);

            if (firstCurr != null) firstCurr = firstCurr.next;
            if (secondCurr != null) secondCurr = secondCurr.next;

            resultCurr = resultCurr.next;
        }

        if(carry!=0){
            resultCurr.next = new ListNode(carry);
        }

        return dummyNode.next;

    }

    private (int digit, int carry) Decompose(int sum){
        if(sum<10){
            return (sum, 0);
        }
        else{
            return (sum-(sum/10)*10,(sum/10));
        }
    }

}


