          }

          // Step 2: check every course for a cycle
          for (int i = 0; i < numCourses; i++) {
              if (HasCycle(i, new HashSet<int>(), dict)) return false;
          }

          return true;
      }

      private bool HasCycle(int course, HashSet<int> seen, Dictionary<int, List<int>> dict) {
          // already visited in this chain → cycle found
          if (seen.Contains(course)) return true;

          // no prerequisites → no cycle possible from here
          if (!dict.ContainsKey(course)) return false;

          // mark this course as visited in the current chain
          seen.Add(course);

          // follow every prerequisite recursively
          foreach (int prereq in dict[course]) {
              if (HasCycle(prereq, seen, dict)) return true;
          }

          // done with this path — unmark so other paths can use this course
          seen.Remove(course);
          return false;
      }
  }

  class Program {
      static void Main() {
          var sol = new Solution();

          // single prereq, no cycle
          bool r1 = sol.CanFinish(2, new int[][]{ new int[]{1,0} });
          Console.WriteLine(r1 == true ? "PASS" : "FAIL");

          // 2-node cycle: 1 needs 0, 0 needs 1
          bool r2 = sol.CanFinish(2, new int[][]{ new int[]{1,0}, new int[]{0,1} });
          Console.WriteLine(r2 == false ? "PASS" : "FAIL");

          // 4-course chain, no cycle
          bool r3 = sol.CanFinish(4, new int[][]{ new int[]{1,0}, new int[]{2,1}, new int[]{3,2} });
          Console.WriteLine(r3 == true ? "PASS" : "FAIL");

          // 3-node cycle: 0→1→2→0
          bool r4 = sol.CanFinish(3, new int[][]{ new int[]{1,0}, new int[]{2,1}, new int[]{0,2} });
          Console.WriteLine(r4 == false ? "PASS" : "FAIL");

          // course with no prerequisites at all
          bool r5 = sol.CanFinish(1, new int[][]{});
          Console.WriteLine(r5 == true ? "PASS" : "FAIL");
      }
  }

